def diagnose_throttling(reason,resource_arn):
    if not isinstance(reason,str) or not isinstance(resource_arn,str):raise ValueError("reason and resource ARN must be strings")
    parts=resource_arn.split(":table/",1)
    if len(parts)!=2 or not parts[1]:raise ValueError("invalid DynamoDB table/index ARN")
    resource=parts[1].split("/index/",1)
    is_index=len(resource)==2
    target=resource[1] if is_index else resource[0]
    if reason.startswith("Index")!=is_index:raise ValueError("throttling reason resource type disagrees with ARN")
    if "WriteProvisionedThroughputExceeded" in reason:
        action="increase or autoscale the identified GSI write capacity; inspect its WriteProvisionedThroughputThrottleEvents and ConsumedWriteCapacityUnits; base-table headroom does not disprove GSI back-pressure"
    elif "KeyRangeThroughputExceeded" in reason:
        action="identify hot partition keys and improve write distribution; raising total index capacity alone may not fix a single hot key"
    elif "AccountLimitExceeded" in reason:action="check account-level on-demand throughput quota for the identified resource"
    else:action="inspect the complete reason and matching table/index metrics before changing capacity"
    return {"resource_type":"index" if is_index else "table","resource_name":target,"reason":reason,"action":action}
```

